export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: COMMAND, description: 'Bật giao diện Thiên hà' })
    const unpainted = problems.find(line => line.startsWith("Desktop won't paint"))

    if (unpainted !== undefined) {
      $.ui.toast(unpainted)
    }

    // Reopen the look picked last. A look never picked yet (just installed) puts itself on; with several
    // installed, the first to set marks the others 'off' through their theme.set hooks.
    if ((await $.store.get(STORE_KEY)) !== 'off') {
      await $.theme.set(LOOK)
    }

    return next(e)
  })

  // Every look set in the session, this mod's or another's, passes here: remember whether it is this one.
  on('theme.set', async ($, e, next) => {
    const result = await next(e)
    const scene = (e.backdrop as { scene?: string } | undefined)?.scene

    await $.store.set(STORE_KEY, scene === SCENE_NAME ? 'on' : 'off')

    return result
  })

  on('command.run', { command: COMMAND }, async $ => {
    await $.theme.set(LOOK)

    return { text: 'Đã bật giao diện Thiên hà.' }
  })

  // The desktop app may not route a runtime-registered slash command, so the same words typed
  // as a prompt switch the look and never reach the model.
  on('prompt.submit', async ($, e, next) => {
    const said = e.text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/gi, 'd').toLowerCase().trim()

    if (/^\/?giao[\s-]*dien[\s-]*thien[\s-]*ha\.?$/.test(said)) {
      await $.theme.set(LOOK)

      return { drop: 'Đã bật giao diện Thiên hà.' }
    }

    return next(e)
  })

  on('ui.render', { component: 'Backdrop' }, ($, e, next) => {
    if ((e.surface !== 'desktop' && e.surface !== 'mobile') || e.props.scene !== SCENE_NAME) {
      return next(e)
    }
    const { Svg } = $.ui.resolve(e)

    return <Svg source={SCENE} alt="Thiên hà: Thiên hà xoắn ốc xoay chậm, tinh vân tím hồng, sao băng vụt qua." isInteractive />
  })
}
